      // HP=200 → 150;revive 检 HP==0 → skip;final HP=150
      expect(gs.PlayerRolesRuntime.rgwHP[0]).toBe(150)
    })
    it('多 op chain 扣尽最后 50 HP 后复活(HP=0 → maxHP * 1/10)', () => {
